from PIL import Image
import numpy as np

def matrix_to_image_from_line(input_line, rows, cols, output_path="output_image1.png"):
    """
    Converts a single-line row-major matrix with float pixel values into a grayscale image and saves it.

    Args:
        input_line (str): A string of space-separated pixel values (floats between 0 and 1).
        rows (int): Number of rows in the matrix.
        cols (int): Number of columns in the matrix.
        output_path (str): Path to save the resulting image.
    """
    # Split the input line into a list of floats
    pixel_values = list(map(float, input_line.split()))
    
    # Check if the number of values matches the expected matrix size
    if len(pixel_values) != rows * cols:
        raise ValueError("Input data size does not match specified dimensions.")
    
    # Normalize float values to the range [0, 255] and convert to integers
    pixel_values = np.clip(np.array(pixel_values) * 255, 0, 255).astype(np.uint8)
    
    # Convert the flat list into a 2D NumPy array
    matrix = pixel_values.reshape(rows, cols)
    
    # Create an image from the matrix
    image = Image.fromarray(matrix, mode='L')  # 'L' mode is for grayscale
    
    # Save the image
    image.save(output_path)
    print(f"Image saved at {output_path}")

